-- 21 questions, all confidence >=4 (verified vs OpenStax Chemistry: Atoms First 2e Ch.7; every oxidation number, electron count, and balancing coefficient independently re-computed).
-- Cross-batch + cross-chapter deduped (esp. vs Ch4 Types-of-Reactions / Balancing-redox / Ions-Electrolytes); final dedup audit PASS (0 genuine conflicts) after a systematic recall-answer-leak sweep.
-- AAMC foundations in this batch: 4E (per-row foundation/content_category below). Answer key balanced A/B/C/D = 18/18/18/18 across the full 72-question chapter.
-- Re-runnable: subtopic-scoped DELETE. Run the four batches in any order in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'Oxidation-Reduction Reactions' AND subtopic IN ('Common Oxidizing & Reducing Agents', 'Balancing Redox (Half-Reaction Method)');

-- Q1 [Common Oxidizing & Reducing Agents · easy · Skill 1 · 4E Stoichiometry (GC) · ans C] (g27)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt27$Sodium metal reacts vigorously with water according to \(2\,\text{Na} + 2\,\text{H}_2\text{O} \rightarrow 2\,\text{NaOH} + \text{H}_2\). Which species acts as the reducing agent in this reaction?$qt27$,
    $op27$[{"label":"A","text":"\\(\\text{H}_2\\text{O}\\), because it donates electrons to the sodium."},{"label":"B","text":"\\(\\text{NaOH}\\), one of the products of the reaction."},{"label":"C","text":"\\(\\text{Na}\\), because it is oxidized from \\(0\\) to \\(+1\\), donating electrons."},{"label":"D","text":"\\(\\text{H}_2\\), one of the products of the reaction."}]$op27$::jsonb,
    'C',
    $ex27$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is C because the reducing agent is the species that is itself oxidized, donating the electrons that reduce something else. Sodium goes from an oxidation state of \(0\) in \(\text{Na}\) to \(+1\) in \(\text{NaOH}\), losing one electron per atom, so it is oxidized and serves as the reducing agent. The hydrogen of water is reduced (from \(+1\) to \(0\) in \(\text{H}_2\)), which makes water the oxidizing agent. (Choice A) Water is reduced in this reaction, gaining the electrons; a species that is reduced is the oxidizing agent, not the reducing agent. (Choice B) \(\text{NaOH}\) is a product of the reaction, not a reactant that supplies electrons. (Choice D) \(\text{H}_2\) is a product formed when hydrogen is reduced, not the species that donates electrons. Skill 1$ex27$,
    'easy', '4E', $cc27$Stoichiometry (GC)$cc27$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a27A$names water (the oxidizing agent) as the electron donor$a27A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a27B$picks a product instead of the oxidized reactant$a27B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a27D$picks a product instead of the oxidized reactant$a27D$ FROM q;

-- Q2 [Common Oxidizing & Reducing Agents · easy · Skill 1 · 4E Stoichiometry (GC) · ans D] (g28)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt28$Lithium aluminum hydride, \(\text{LiAlH}_4\), is widely used in chemical synthesis. In this compound, each hydrogen carries an oxidation state of \(-1\), making it a hydride donor. Based on this property, how does \(\text{LiAlH}_4\) typically behave when it reacts with another species?$qt28$,
    $op28$[{"label":"A","text":"It acts as a strong oxidizing agent, donating hydride ions that remove electrons from the other species."},{"label":"B","text":"It acts as a strong oxidizing agent, accepting electrons from the other species as its hydrogens are reduced."},{"label":"C","text":"It acts as a strong reducing agent because its aluminum center readily accepts electrons from the other species."},{"label":"D","text":"It acts as a strong reducing agent, donating hydride ions and thereby supplying electrons to the other species."}]$op28$::jsonb,
    'D',
    $ex28$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because a reducing agent is the species that donates electrons (and is itself oxidized) during a redox reaction. In \(\text{LiAlH}_4\), lithium is \(+1\) and aluminum is \(+3\); since the molecule is neutral, the four hydrogens must collectively account for \(-4\), so each hydrogen is \(-1\) (a hydride ion, \(\text{H}^-\)). These hydride ions are electron-rich and are readily transferred to electron-poor centers, supplying electrons to the species being reduced. By furnishing \(\text{H}^-\) and electrons, \(\text{LiAlH}_4\) functions as a strong reducing agent. (Choice A) This choice contains two errors: it mislabels \(\text{LiAlH}_4\) as an oxidizing agent, and it describes hydride donation as removing electrons; donating electron-rich \(\text{H}^-\) supplies electrons, making \(\text{LiAlH}_4\) a reducing agent. (Choice B) This reverses the role of \(\text{LiAlH}_4\): an oxidizing agent accepts electrons, but \(\text{LiAlH}_4\) donates electrons via its hydride ions, so it is a reducing agent, not an oxidizing agent. (Choice C) Although this choice correctly labels \(\text{LiAlH}_4\) as a reducing agent, its mechanism is wrong; the reducing power comes from the donation of hydride ions, not from the aluminum center accepting electrons, and a reducing agent donates rather than accepts electrons. Skill 1$ex28$,
    'easy', '4E', $cc28$Stoichiometry (GC)$cc28$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a28A$Believes hydride donation removes electrons, mislabeling the agent as oxidizing$a28A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a28B$Swaps reducing-agent role for oxidizing-agent role (donor treated as acceptor)$a28B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a28C$Correct reducing-agent label but wrong mechanism (Al accepting electrons instead of H- donation)$a28C$ FROM q;

-- Q3 [Common Oxidizing & Reducing Agents · easy · Skill 2 · 4E Stoichiometry (GC) · ans A] (g29)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt29$In an acidic redox titration, potassium dichromate, \(\text{K}_2\text{Cr}_2\text{O}_7\), is consumed as each chromium atom changes from an oxidation state of \(+6\) in the dichromate ion, \(\text{Cr}_2\text{O}_7^{2-}\), to \(+3\) in \(\text{Cr}^{3+}\). Based on this change, how should \(\text{K}_2\text{Cr}_2\text{O}_7\) be classified in this reaction?$qt29$,
    $op29$[{"label":"A","text":"It is the oxidizing agent, because the chromium is reduced."},{"label":"B","text":"It is the reducing agent, because the chromium is oxidized."},{"label":"C","text":"It is the reducing agent, because the chromium is reduced."},{"label":"D","text":"It is the oxidizing agent, because the chromium is oxidized."}]$op29$::jsonb,
    'A',
    $ex29$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because the chromium oxidation state decreases from \(+6\) to \(+3\), which is a gain of three electrons per chromium atom and therefore a reduction. (In \(\text{Cr}_2\text{O}_7^{2-}\), each oxygen is \(-2\) and the overall charge is \(-2\), so \(2(\text{Cr}) + 7(-2) = -2\), giving \(\text{Cr} = +6\); in \(\text{Cr}^{3+}\) the oxidation state is \(+3\).) The species that is reduced is, by definition, the oxidizing agent—it accepts electrons and thereby oxidizes another species. Since the chromium in \(\text{K}_2\text{Cr}_2\text{O}_7\) is reduced, \(\text{K}_2\text{Cr}_2\text{O}_7\) is the oxidizing agent. (Choice B) This both mislabels the agent and misidentifies the direction of change: a drop from \(+6\) to \(+3\) is a decrease in oxidation number, so the chromium is reduced, not oxidized, and the species is therefore not the reducing agent. (Choice C) The direction of electron transfer is correctly identified as reduction, but the classification is reversed—the species that is reduced is the oxidizing agent, not the reducing agent. (Choice D) The classification as the oxidizing agent is correct, but the stated reason is wrong: a change from \(+6\) to \(+3\) is a gain of electrons (reduction), not oxidation. Skill 2$ex29$,
    'easy', '4E', $cc29$Stoichiometry (GC)$cc29$, 'general-chemistry', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a29B$Calls the species reduced the reducing agent and reverses the direction of oxidation-state change$a29B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a29C$Correct that Cr is reduced but swaps oxidizing agent for reducing agent$a29C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a29D$Correct oxidizing-agent label paired with the wrong reason (oxidation instead of reduction)$a29D$ FROM q;

-- Q4 [Common Oxidizing & Reducing Agents · medium · Skill 2 · 4E Stoichiometry (GC) · ans B] (g30)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt30$In many catabolic pathways, an enzyme oxidizes a substrate by removing two hydrogen atoms; one is transferred to \(\text{NAD}^+\) as a hydride ion (\(\text{H}^-\), a proton carrying two electrons) while the second leaves as a free proton, according to the net transfer \(\text{NAD}^+ + \text{H}^- \rightarrow \text{NADH}\). On the basis of the electrons exchanged in this step, what role does \(\text{NAD}^+\) play in the reaction?$qt30$,
    $op30$[{"label":"A","text":"It is the reducing agent, because it accepts the two electrons of the hydride and is itself oxidized to \\(\\text{NADH}\\)."},{"label":"B","text":"It is the oxidizing agent, because it accepts the two electrons of the hydride and is itself reduced to \\(\\text{NADH}\\)."},{"label":"C","text":"It is the reducing agent, because by donating the hydride to the substrate it is itself oxidized to \\(\\text{NADH}\\)."},{"label":"D","text":"It is the oxidizing agent, because the free proton released to solution carries away two electrons and oxidizes \\(\\text{NAD}^+\\)."}]$op30$::jsonb,
    'B',
    $ex30$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because the oxidizing agent is the species that causes another species to be oxidized and is itself reduced by gaining electrons. A hydride ion, \(\text{H}^-\), is a single proton accompanied by two electrons, so the transfer \(\text{NAD}^+ + \text{H}^- \rightarrow \text{NADH}\) delivers two electrons to \(\text{NAD}^+\). Gaining electrons is reduction, so \(\text{NAD}^+\) is reduced to \(\text{NADH}\); a species that is reduced is by definition the oxidizing agent (it oxidizes the substrate, which loses the hydride and is therefore oxidized). The charge bookkeeping confirms this: \(\text{NAD}^+\) (net \(+1\)) plus \(\text{H}^-\) (net \(-1\)) gives neutral \(\text{NADH}\), consistent with the addition of two electrons along with one proton. (Choice A) This choice correctly identifies that \(\text{NAD}^+\) accepts the two electrons but then mislabels electron gain as oxidation; gaining electrons is reduction, and a species that is reduced is the oxidizing agent, not the reducing agent. (Choice C) This choice reverses the direction of hydride transfer: in dehydrogenation the substrate donates the hydride and \(\text{NAD}^+\) accepts it, so \(\text{NAD}^+\) is reduced (oxidizing agent), not oxidized (reducing agent). (Choice D) This choice reaches the correct label by faulty reasoning; the released species is a bare proton (\(\text{H}^+\)) that carries no electrons, and \(\text{NAD}^+\) is reduced by accepting the hydride's two electrons rather than being oxidized by the proton. Skill 2$ex30$,
    'medium', '4E', $cc30$Stoichiometry (GC)$cc30$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a30A$Equates electron gain with oxidation, mislabeling the reduced species as the reducing agent$a30A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a30C$Reverses the direction of hydride transfer so NAD+ is treated as donor and thus oxidized$a30C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a30D$Right label via wrong step: attributes electron carriage to the released proton instead of the hydride$a30D$ FROM q;

-- Q5 [Common Oxidizing & Reducing Agents · medium · Skill 3 · 4E Stoichiometry (GC) · ans C] (g31)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt31$Hydrogen peroxide, \(\text{H}_2\text{O}_2\), is unusual in that it can behave either as an oxidizing agent or as a reducing agent, depending on its reaction partner. Consider the acidic reaction \(\text{H}_2\text{O}_2 + 2\,\text{I}^- + 2\,\text{H}^+ \rightarrow \text{I}_2 + 2\,\text{H}_2\text{O}\). Based on the oxidation-state changes that occur, what role does \(\text{H}_2\text{O}_2\) play in this specific reaction?$qt31$,
    $op31$[{"label":"A","text":"It acts as the reducing agent, because its oxygen is reduced from \\(-1\\) to \\(-2\\) while it donates electrons to iodide."},{"label":"B","text":"It acts as the reducing agent, because its oxygen is oxidized from \\(-1\\) to \\(0\\) as it is converted to \\(\\text{O}_2\\)."},{"label":"C","text":"It acts as the oxidizing agent, because its oxygen is reduced (gaining electrons) as it is converted to \\(\\text{H}_2\\text{O}\\)."},{"label":"D","text":"It acts as the oxidizing agent, because its hydrogen is oxidized from \\(+1\\) to \\(0\\) as the peroxide bond breaks."}]$op31$::jsonb,
    'C',
    $ex31$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. In \(\text{H}_2\text{O}_2\) each hydrogen is \(+1\) and, for the neutral molecule to sum to zero, each oxygen must be \(-1\); this intermediate value (between \(0\) in \(\text{O}_2\) and \(-2\) in \(\text{H}_2\text{O}\)) is what lets peroxide act either way. The answer to this question is C because the oxygen-bookkeeping for this reaction shows oxygen being reduced: in the product \(\text{H}_2\text{O}\) each oxygen is \(-2\) (H is \(+1\), so \(2(+1)+x=0\) gives \(x=-2\)), a drop from \(-1\) to \(-2\). A species whose own element gains electrons (is reduced) is the oxidizing agent, so \(\text{H}_2\text{O}_2\) is the oxidizing agent here. The partner confirms this: iodine in \(\text{I}^-\) goes from \(-1\) to \(0\) in \(\text{I}_2\) (oxidized), making iodide the reducing agent. The half-reaction \(\text{H}_2\text{O}_2 + 2\,\text{H}^+ + 2\,e^- \rightarrow 2\,\text{H}_2\text{O}\) explicitly shows peroxide consuming electrons, the defining behavior of an oxidizing agent. (Choice A) The oxidation-state change is read correctly as a reduction from \(-1\) to \(-2\), but the label is reversed: a species that is itself reduced acts as the oxidizing agent, not the reducing agent, since it accepts the electrons that iodide donates. (Choice B) This correctly describes peroxide's other possible role, in which oxygen is oxidized from \(-1\) to \(0\) and \(\text{O}_2\) is released, but that is not what happens in this reaction; here the product is \(\text{H}_2\text{O}\) (oxygen \(-2\)), not \(\text{O}_2\), so peroxide is reduced rather than oxidized. (Choice D) Hydrogen remains \(+1\) on both sides (it is \(+1\) in \(\text{H}_2\text{O}_2\) and \(+1\) in \(\text{H}_2\text{O}\)); it is never reduced to \(0\), so the redox change is carried by oxygen, not hydrogen, and this reasoning misidentifies which atom changes oxidation state. Skill 3$ex31$,
    'medium', '4E', $cc31$Stoichiometry (GC)$cc31$, 'general-chemistry', 3, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a31A$correct reduction read but oxidizing/reducing-agent labels swapped$a31A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a31B$describes peroxide's other (reducing-agent) role not occurring in this reaction$a31B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a31D$assigns the redox change to hydrogen instead of oxygen$a31D$ FROM q;

-- Q6 [Common Oxidizing & Reducing Agents · medium · Skill 3 · 4E Stoichiometry (GC) · ans D] (g32)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Common Oxidizing & Reducing Agents',
    $qt32$A synthetic chemist needs a reagent that will oxidize a primary alcohol to an aldehyde without carrying the oxidation further to the carboxylic acid. The chemist must select an agent in which the metal center is a chromium(VI) species. Which of the following reagents satisfies both requirements?$qt32$,
    $op32$[{"label":"A","text":"Aqueous chromic acid (Jones reagent), \\(\\text{H}_2\\text{CrO}_4\\)"},{"label":"B","text":"Acidic potassium permanganate, \\(\\text{KMnO}_4/\\text{H}^+\\)"},{"label":"C","text":"Lithium aluminum hydride, \\(\\text{LiAlH}_4\\)"},{"label":"D","text":"Pyridinium chlorochromate, \\(\\text{C}_5\\text{H}_5\\text{NH}^+[\\text{ClCrO}_3]^-\\) (PCC)"}]$op32$::jsonb,
    'D',
    $ex32$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because pyridinium chlorochromate (PCC) contains chromium in the \(+6\) state and is the mild, anhydrous oxidant that stops a primary alcohol at the aldehyde. The oxidation state of Cr in the chlorochromate anion \([\text{ClCrO}_3]^-\) is found by setting the sum of oxidation numbers equal to the ion charge: chlorine contributes \(-1\) and the three oxygens contribute \(3\times(-2)=-6\), so \(x + (-1) + (-6) = -1\), giving \(x = +6\). PCC is therefore a Cr(VI) oxidant. Because PCC is used under anhydrous (non-aqueous) conditions, the aldehyde formed from a primary alcohol cannot be hydrated to the gem-diol intermediate required for further oxidation, so the reaction halts cleanly at the aldehyde and satisfies both stated requirements. (Choice A) Aqueous chromic acid (Jones reagent) does contain chromium(VI) (in \(\text{H}_2\text{CrO}_4\): \(2(+1) + x + 4(-2) = 0\), so \(x=+6\)), but because it is used in water it overoxidizes a primary alcohol past the aldehyde to the carboxylic acid; it meets the metal requirement yet fails the selectivity requirement. (Choice B) Acidic \(\text{KMnO}_4\) is a strong oxidizing agent, but its metal center is manganese in the \(+7\) state (in \(\text{MnO}_4^-\): \(x + 4(-2) = -1\), so \(x=+7\)), not chromium(VI); moreover, as a strong aqueous oxidant it would overoxidize the primary alcohol all the way to the carboxylic acid, failing both conditions. (Choice C) \(\text{LiAlH}_4\) is a hydride source and acts as a reducing agent, not an oxidizing agent; it would drive the reaction in the opposite direction (e.g., reducing a carbonyl to an alcohol) and contains aluminum, not chromium, so it cannot oxidize an alcohol to an aldehyde at all. Skill 3$ex32$,
    'medium', '4E', $cc32$Stoichiometry (GC)$cc32$, 'general-chemistry', 3, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a32A$Correct Cr(VI) metal but aqueous conditions overoxidize to carboxylic acid, failing selectivity$a32A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a32B$Cites a strong oxidant whose metal is Mn(+7), not Cr(VI), and which overoxidizes$a32B$ FROM q
