UNION ALL SELECT id, 'B', 'misconception', $a36B$hydride reduces every carbonyl indiscriminately$a36B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a36C$acid carbonyl reduced preferentially over ketone$a36C$ FROM q;

-- Q11 [Balancing Redox (Half-Reaction Method) · easy · Skill 1 · 4E Stoichiometry (GC) · ans A] (g37)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt37$Consider the reduction of molecular oxygen to water in acidic solution, represented by the skeleton half-reaction \(\text{O}_2 \rightarrow \text{H}_2\text{O}\) (acidic). When this half-reaction is fully balanced, how many electrons must be supplied per \(\text{O}_2\) molecule reduced?$qt37$,
    $op37$[{"label":"A","text":"\\(4\\) electrons"},{"label":"B","text":"\\(2\\) electrons"},{"label":"C","text":"\\(1\\) electron"},{"label":"D","text":"\\(8\\) electrons"}]$op37$::jsonb,
    'A',
    $ex37$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because each oxygen atom is reduced from an oxidation state of \(0\) in \(\text{O}_2\) to \(-2\) in \(\text{H}_2\text{O}\), a gain of \(2\) electrons per atom; since one \(\text{O}_2\) molecule contains two oxygen atoms, the molecule gains \(2 \times 2 = 4\) electrons, giving the balanced half-reaction \(\text{O}_2 + 4\text{H}^+ + 4e^- \rightarrow 2\text{H}_2\text{O}\). (Choice B) \(2\) electrons counts only the change for a single oxygen atom and forgets that \(\text{O}_2\) contains two oxygen atoms, each gaining two electrons. (Choice C) \(1\) electron matches neither the per-atom change (which is \(2\)) nor the per-molecule total (which is \(4\)). (Choice D) \(8\) electrons doubles the correct count, as if each oxygen gained four electrons, but the change from \(0\) to \(-2\) is only two electrons per atom. Skill 1$ex37$,
    'easy', '4E', $cc37$Stoichiometry (GC)$cc37$, 'general-chemistry', 1, 75
  ) RETURNING id
)
