UNION ALL SELECT id, 'D', 'process_step_confusion', $a37D$doubles the correct electron count$a37D$ FROM q;

-- Q12 [Balancing Redox (Half-Reaction Method) · easy · Skill 2 · 4E Stoichiometry (GC) · ans B] (g38)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt38$In acidic solution, chlorate ion is reduced to chloride ion. A student balancing the skeleton half-reaction \(\text{ClO}_3^- \rightarrow \text{Cl}^-\) (acidic) by the half-reaction method must account for the oxygen atoms with water and then balance the resulting hydrogen atoms with \(\text{H}^+\). How many \(\text{H}^+\) ions are required to balance this half-reaction, and on which side are they added?$qt38$,
    $op38$[{"label":"A","text":"\\(3\\;\\text{H}^+\\) on the left (reactant) side"},{"label":"B","text":"\\(6\\;\\text{H}^+\\) on the left (reactant) side"},{"label":"C","text":"\\(6\\;\\text{H}^+\\) on the right (product) side"},{"label":"D","text":"\\(6\\;\\text{OH}^-\\) on the left (reactant) side"}]$op38$::jsonb,
    'B',
    $ex38$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because in acidic medium the half-reaction is balanced by first balancing the element other than O and H (chlorine is already \(1\) on each side), then balancing oxygen with water, and finally balancing hydrogen with \(\text{H}^+\). The reactant \(\text{ClO}_3^-\) carries \(3\) oxygen atoms while the product \(\text{Cl}^-\) carries none, so \(3\,\text{H}_2\text{O}\) are added on the right to balance oxygen: \(\text{ClO}_3^- \rightarrow \text{Cl}^- + 3\,\text{H}_2\text{O}\). Those \(3\,\text{H}_2\text{O}\) introduce \(6\) hydrogen atoms on the right, so \(6\,\text{H}^+\) must be added on the left to balance hydrogen, giving \(\text{ClO}_3^- + 6\,\text{H}^+ + 6e^- \rightarrow \text{Cl}^- + 3\,\text{H}_2\text{O}\). The \(\text{H}^+\) belong on the reactant (left) side. (Choice A) \(3\,\text{H}^+\) on the left matches the number of oxygen atoms rather than the number of hydrogen atoms supplied by \(3\,\text{H}_2\text{O}\); each water contributes two hydrogens, so \(6\,\text{H}^+\) are needed, not \(3\). (Choice C) Placing \(6\,\text{H}^+\) on the right doubles the hydrogen on the product side instead of balancing it, leaving the equation with \(12\) H on the right and none on the left. (Choice D) Hydroxide ions are used to balance hydrogen in basic solution; in acidic solution hydrogen is balanced with \(\text{H}^+\), so \(\text{OH}^-\) is not the appropriate species here. Skill 2$ex38$,
    'easy', '4E', $cc38$Stoichiometry (GC)$cc38$, 'general-chemistry', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a38A$matches H+ count to the number of oxygen atoms instead of hydrogen atoms$a38A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a38C$places H+ on the same side as the water rather than the opposite side$a38C$ FROM q
