-- Q13 [Balancing Redox (Half-Reaction Method) · medium · Skill 2 · 4E Stoichiometry (GC) · ans C] (g39)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt39$When the half-reaction method is used to balance the reduction of nitrate ion to nitric oxide in acidic solution, the unbalanced skeleton half-reaction is \(\text{NO}_3^- \rightarrow \text{NO}\). After the half-reaction is fully balanced for mass and charge in acidic medium, what is the coefficient of \(\text{H}_2\text{O}\)?$qt39$,
    $op39$[{"label":"A","text":"3"},{"label":"B","text":"1"},{"label":"C","text":"2"},{"label":"D","text":"4"}]$op39$::jsonb,
    'C',
    $ex39$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is C because balancing \(\text{NO}_3^- \rightarrow \text{NO}\) by the half-reaction method in acid proceeds in a fixed order. First balance the atom undergoing redox: nitrogen is already balanced (1 N on each side). Next balance oxygen by adding \(\text{H}_2\text{O}\): the left side has 3 O (in \(\text{NO}_3^-\)) and the right side has 1 O (in \(\text{NO}\)), a difference of 2 O, so 2 \(\text{H}_2\text{O}\) must be added to the right, giving \(\text{NO}_3^- \rightarrow \text{NO} + 2\,\text{H}_2\text{O}\). Then balance hydrogen with \(\text{H}^+\): the right now has 4 H (from 2 \(\text{H}_2\text{O}\)), so add 4 \(\text{H}^+\) to the left, giving \(4\,\text{H}^+ + \text{NO}_3^- \rightarrow \text{NO} + 2\,\text{H}_2\text{O}\). Finally balance charge with electrons: the left has a net charge of \(4(+1) + (-1) = +3\) and the right is \(0\), so add 3 \(e^-\) to the left: \(3\,e^- + 4\,\text{H}^+ + \text{NO}_3^- \rightarrow \text{NO} + 2\,\text{H}_2\text{O}\). This 3-electron gain is consistent with nitrogen being reduced from \(+5\) in \(\text{NO}_3^-\) to \(+2\) in \(\text{NO}\). Therefore the coefficient of \(\text{H}_2\text{O}\) is 2. (Choice A) A coefficient of 3 incorrectly sets the number of \(\text{H}_2\text{O}\) equal to the 3 electrons transferred (the \(+5 \rightarrow +2\) change), confusing the electron count with the water coefficient. (Choice B) A coefficient of 1 would only balance one oxygen atom on the right, leaving the oxygen mass unbalanced (3 O on the left versus 2 O on the right); it reflects adding a single water molecule without matching the full oxygen deficit. (Choice D) A coefficient of 4 mistakes the number of \(\text{H}^+\) ions (4) for the number of water molecules, swapping the hydrogen-balancing step with the oxygen-balancing step. Skill 2$ex39$,
    'medium', '4E', $cc39$Stoichiometry (GC)$cc39$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a39A$equates water coefficient with electron count$a39A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a39B$adds one water, ignores full oxygen deficit$a39B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a39D$mistakes the H+ count for the H2O count$a39D$ FROM q;

-- Q14 [Balancing Redox (Half-Reaction Method) · medium · Skill 2 · 4E Stoichiometry (GC) · ans D] (g40)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt40$In acidic solution, nitrate ion can be reduced all the way to ammonium ion according to the unbalanced skeleton half-reaction \(\text{NO}_3^- \rightarrow \text{NH}_4^+\). When this half-reaction is balanced by the half-reaction method, how many electrons are transferred per nitrate ion reduced?$qt40$,
    $op40$[{"label":"A","text":"\\(3\\) electrons"},{"label":"B","text":"\\(5\\) electrons"},{"label":"C","text":"\\(6\\) electrons"},{"label":"D","text":"\\(8\\) electrons"}]$op40$::jsonb,
    'D',
    $ex40$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because the number of electrons transferred equals the magnitude of the change in nitrogen's oxidation state. In \(\text{NO}_3^-\), each oxygen is \(-2\) (total \(-6\)) and the ion charge is \(-1\), so nitrogen is \(+5\). In \(\text{NH}_4^+\), each hydrogen is \(+1\) (total \(+4\)) and the ion charge is \(+1\), so nitrogen is \(-3\). Going from \(+5\) to \(-3\) is a gain of \(8\) units of negative charge, meaning \(8\) electrons are added per nitrogen atom; this is confirmed by the balanced reduction half-reaction \(\text{NO}_3^- + 10\,\text{H}^+ + 8e^- \rightarrow \text{NH}_4^+ + 3\,\text{H}_2\text{O}\). (Choice A) \(3\) electrons reflects only the magnitude of the final oxidation state \(-3\) itself rather than the full \(+5\) to \(-3\) change. (Choice B) \(5\) electrons would correspond to a change from \(+5\) only down to \(0\), which is the nitrogen oxidation state in \(\text{N}_2\), not the \(-3\) of ammonium. (Choice C) \(6\) electrons would arise from incorrectly using \(-1\) (rather than \(-3\)) as nitrogen's final oxidation state, miscounting the change as \(+5\) to \(-1\). Skill 2$ex40$,
    'medium', '4E', $cc40$Stoichiometry (GC)$cc40$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
