UNION ALL SELECT id, 'B', 'process_step_confusion', $a44B$Uses the unscaled reduction half-reaction's H+ count, forgetting it is doubled when that half-reaction is scaled to 10 electrons$a44B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a44C$Reports the equalized electron count (LCM of 5 and 2) as the H+ coefficient$a44C$ FROM q;

-- Q19 [Balancing Redox (Half-Reaction Method) · hard · Skill 4 · 4E Stoichiometry (GC) · ans A] (g45)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt45$Consider the balanced redox reaction \(2\,\text{S}_2\text{O}_3^{2-} + \text{I}_2 \rightarrow \text{S}_4\text{O}_6^{2-} + 2\,\text{I}^-\), used in iodometric titrations. How many electrons are transferred in this reaction as written?$qt45$,
    $op45$[{"label":"A","text":"\\(2\\) electrons"},{"label":"B","text":"\\(1\\) electron"},{"label":"C","text":"\\(4\\) electrons"},{"label":"D","text":"\\(6\\) electrons"}]$op45$::jsonb,
    'A',
    $ex45$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because the electrons gained by the species reduced equal the electrons lost by the species oxidized. Each iodine atom in \(\text{I}_2\) (oxidation state \(0\)) becomes \(\text{I}^-\) (\(-1\)), gaining one electron, so the two iodine atoms gain \(2\) electrons in total. Correspondingly, the sulfur of two thiosulfate ions (average \(+2\)) is oxidized to tetrathionate \(\text{S}_4\text{O}_6^{2-}\) (average \(+2.5\)), releasing \(2\) electrons in total. Thus \(2\) electrons are transferred. (Choice B) \(1\) electron accounts for only a single iodine atom, but \(\text{I}_2\) contains two iodine atoms, each gaining one electron. (Choice C) \(4\) electrons doubles the correct count. (Choice D) \(6\) electrons does not match the one-electron-per-iodine change across the two iodine atoms. Skill 4$ex45$,
    'hard', '4E', $cc45$Stoichiometry (GC)$cc45$, 'general-chemistry', 4, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a45B$counts only one iodine atom instead of the two in I2$a45B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a45C$doubles the correct electron count$a45C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a45D$electron count unrelated to the per-iodine change$a45D$ FROM q;

-- Q20 [Balancing Redox (Half-Reaction Method) · hard · Skill 4 · 4E Stoichiometry (GC) · ans B] (g46)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Balancing Redox (Half-Reaction Method)',
    $qt46$Acidic dichromate is a strong oxidant frequently used to titrate iron(II). When dichromate ion oxidizes iron(II) to iron(III) in acidic solution, the unbalanced skeleton is \(\text{Cr}_2\text{O}_7^{2-} + \text{Fe}^{2+} + \text{H}^+ \rightarrow \text{Cr}^{3+} + \text{Fe}^{3+} + \text{H}_2\text{O}\). Using the half-reaction method, what is the stoichiometric coefficient of \(\text{Fe}^{3+}\) in the fully balanced overall equation (smallest whole-number coefficients)?$qt46$,
    $op46$[{"label":"A","text":"3"},{"label":"B","text":"6"},{"label":"C","text":"2"},{"label":"D","text":"14"}]$op46$::jsonb,
    'B',
    $ex46$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because the two half-reactions must transfer equal numbers of electrons. In the reduction half-reaction, each chromium goes from \(+6\) in \(\text{Cr}_2\text{O}_7^{2-}\) to \(+3\) in \(\text{Cr}^{3+}\); with two chromium atoms that is \(2 \times 3 = 6\) electrons gained: \(\text{Cr}_2\text{O}_7^{2-} + 14\text{H}^+ + 6e^- \rightarrow 2\text{Cr}^{3+} + 7\text{H}_2\text{O}\). In the oxidation half-reaction, iron goes from \(+2\) to \(+3\), losing one electron each: \(\text{Fe}^{2+} \rightarrow \text{Fe}^{3+} + e^-\). To balance the 6 electrons released by the reduction, the iron half-reaction is multiplied by 6: \(6\text{Fe}^{2+} \rightarrow 6\text{Fe}^{3+} + 6e^-\). Adding the half-reactions gives \(\text{Cr}_2\text{O}_7^{2-} + 6\text{Fe}^{2+} + 14\text{H}^+ \rightarrow 2\text{Cr}^{3+} + 6\text{Fe}^{3+} + 7\text{H}_2\text{O}\), so the coefficient of \(\text{Fe}^{3+}\) is \(6\). (Choice A) 3 is the number of electrons gained per single chromium atom (\(+6 \rightarrow +3\)); it would be the electron transfer for only one Cr rather than the total 6 electrons that fix the iron coefficient. (Choice C) 2 is the coefficient of \(\text{Cr}^{3+}\), obtained from the two chromium atoms in \(\text{Cr}_2\text{O}_7^{2-}\); it is mismatched to \(\text{Fe}^{3+}\), which is set by the 6-electron requirement. (Choice D) 14 is the coefficient of \(\text{H}^+\) needed to balance the seven oxygen atoms as water in the reduction half-reaction, not the iron coefficient. Skill 4$ex46$,
    'hard', '4E', $cc46$Stoichiometry (GC)$cc46$, 'general-chemistry', 4, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a46A$Uses electrons-per-single-Cr (3) instead of total 6-electron transfer$a46A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a46C$Copies the Cr3+ coefficient (2) onto Fe3+$a46C$ FROM q
